// Parsear resultado XML de Nmap SIN dependencias externas (solo regex nativo)
const xmlData = $input.first().json.stdout;

const hostBlocks = xmlData.match(/<host[^>]*>[\s\S]*?<\/host>/g) || [];

const hosts = hostBlocks.map(block => {
  const ipMatch = block.match(/<address addr="([^"]+)" addrtype="ipv4"/);
  const stateMatch = block.match(/<status state="([^"]+)"/);
  const hostnameMatch = block.match(/<hostname name="([^"]+)"/);
  const osMatch = block.match(/<osmatch name="([^"]+)"/);

  const portMatches = block.match(/<port protocol="(\w+)" portid="(\d+)">[\s\S]*?<\/port>/g) || [];

  const ports = portMatches.map(portBlock => {
    const protocol = portBlock.match(/protocol="(\w+)"/)?.[1] || '';
    const portid = portBlock.match(/portid="(\d+)"/)?.[1] || '';
    const portState = portBlock.match(/<state state="([^"]+)"/)?.[1] || '';
    const serviceName = portBlock.match(/<service name="([^"]*)"/)?.[1] || 'unknown';
    const serviceVersion = portBlock.match(/version="([^"]*)"/)?.[1] || '';

    return {
      port: portid,
      protocol: protocol,
      state: portState,
      service: serviceName,
      version: serviceVersion
    };
  });

  return {
    ip: ipMatch ? ipMatch[1] : 'Unknown',
    hostname: hostnameMatch ? hostnameMatch[1] : 'Unknown',
    state: stateMatch ? stateMatch[1] : 'Unknown',
    os: osMatch ? osMatch[1] : 'Unknown',
    ports: ports
  };
});

return hosts.map(host => ({ json: host }));

// Junta todas las IPs detectadas por nmap en un solo string CIDR/lista
// para pasarlas como UN SOLO argumento al script de gvm-script.
// Si preferís escanear todo el rango de red en vez de host por host,
// podés directamente hardcodear el rango acá en vez de usar las IPs de nmap.
const items = $input.all();
const ips = items.map(item => item.json.ip).filter(ip => ip && ip !== 'Unknown');

// Opción A: pasar todas las IPs separadas por coma (gvm soporta múltiples hosts así)
const hostsArg = ips.join(',');

return [{ json: { hostsArg } }];

// Parsear vulnerabilidades del XML que devuelve gvm-script (stdout del nodo SSH)
// SIN dependencias externas (solo regex nativo, igual que Parse Nmap XML)
const xmlData = $input.first().json.stdout;

const resultBlocks = xmlData.match(/<result[^>]*>[\s\S]*?<\/result>/g) || [];

const vulnerabilities = resultBlocks.map(block => {
  const nameMatch = block.match(/<name>([^<]*)<\/name>/);
  const severityMatch = block.match(/<severity>([^<]*)<\/severity>/);
  const hostMatch = block.match(/<host[^>]*>([\s\S]*?)<\/host>/);
  const portMatch = block.match(/<port>([^<]*)<\/port>/);
  const descriptionMatch = block.match(/<description>([\s\S]*?)<\/description>/);
  const solutionMatch = block.match(/<solution[^>]*>([\s\S]*?)<\/solution>/);
  const cveMatch = block.match(/<cve>([^<]*)<\/cve>/);

  return {
    name: nameMatch ? nameMatch[1] : 'Unknown',
    severity: severityMatch ? parseFloat(severityMatch[1]) : 0,
    host: hostMatch ? hostMatch[1].replace(/<[^>]+>/g, '').trim() : 'Unknown',
    port: portMatch ? portMatch[1] : '',
    description: descriptionMatch ? descriptionMatch[1].trim() : '',
    solution: solutionMatch ? solutionMatch[1].trim() : 'No solution available',
    cve: cveMatch ? cveMatch[1] : 'N/A'
  };
});

return [{ json: { vulnerabilities, scanDate: new Date().toISOString() } }];

// Aplanar vulnerabilidades a items individuales para insertar en DB
const data = $input.first().json;
const vulnerabilities = data.vulnerabilities;

return vulnerabilities.map(vuln => ({
  json: {
    scan_date: data.scanDate,
    host: vuln.host,
    vulnerability_name: vuln.name,
    severity: vuln.severity,
    port: vuln.port,
    cve: vuln.cve,
    description: vuln.description,
    solution: vuln.solution
  }
}));

const data = $('Parse Results').first().json;
const vulns = data.vulnerabilities;

const critical = vulns.filter(v => v.severity >= 9.0);
const high = vulns.filter(v => v.severity >= 7.0 && v.severity < 9.0);
const medium = vulns.filter(v => v.severity >= 4.0 && v.severity < 7.0);
const low = vulns.filter(v => v.severity < 4.0);

const pct = (n) => vulns.length ? ((n / vulns.length) * 100).toFixed(1) : '0.0';

const report = `
# Informe de Escaneo de Vulnerabilidades

**Fecha del Escaneo**: ${new Date(data.scanDate).toLocaleString('es-AR')}
**Hosts Escaneados**: ${[...new Set(vulns.map(v => v.host))].length}
**Total de Vulnerabilidades**: ${vulns.length}

---

## Resumen Ejecutivo

| Severidad | Cantidad | Porcentaje |
|-----------|----------|------------|
| Critica (9.0-10.0) | ${critical.length} | ${pct(critical.length)}% |
| Alta (7.0-8.9) | ${high.length} | ${pct(high.length)}% |
| Media (4.0-6.9) | ${medium.length} | ${pct(medium.length)}% |
| Baja (0.0-3.9) | ${low.length} | ${pct(low.length)}% |

---

## Vulnerabilidades Criticas

${critical.length > 0 ? critical.map((v, i) => `
### ${i+1}. ${v.name}

**Host**: ${v.host}:${v.port}
**Severidad**: ${v.severity}/10.0
**CVE**: ${v.cve}

**Descripcion**:
${v.description}

**Solucion Recomendada**:
${v.solution}

---
`).join('\n') : '*No se encontraron vulnerabilidades criticas.*\n'}

## Vulnerabilidades Altas

${high.length > 0 ? high.slice(0, 5).map((v, i) => `
### ${i+1}. ${v.name}

**Host**: ${v.host}:${v.port}
**Severidad**: ${v.severity}/10.0
**CVE**: ${v.cve}

**Descripcion**: ${v.description.substring(0, 200)}...

**Solucion**: ${v.solution.substring(0, 200)}...

---
`).join('\n') : '*No se encontraron vulnerabilidades altas.*\n'}

${high.length > 5 ? `*...y ${high.length - 5} vulnerabilidades altas adicionales.*\n` : ''}

## Recomendaciones Generales

1. Priorizar la remediacion de vulnerabilidades criticas inmediatamente
2. Aplicar parches de seguridad en todos los sistemas identificados
3. Revisar configuraciones de servicios expuestos
4. Implementar politicas de actualizacion regular
5. Realizar escaneos de seguimiento despues de aplicar correcciones

---

## Hosts Analizados

${[...new Set(vulns.map(v => v.host))].map(host => {
  const hostVulns = vulns.filter(v => v.host === host);
  return `
### ${host}
- Total vulnerabilidades: ${hostVulns.length}
- Criticas: ${hostVulns.filter(v => v.severity >= 9.0).length}
- Altas: ${hostVulns.filter(v => v.severity >= 7.0 && v.severity < 9.0).length}
- Medias: ${hostVulns.filter(v => v.severity >= 4.0 && v.severity < 7.0).length}
- Bajas: ${hostVulns.filter(v => v.severity < 4.0).length}
`;
}).join('\n')}

---

*Informe generado automaticamente por el sistema de escaneo de vulnerabilidades*
`;

return [{
  json: {
    report: report,
    scanDate: data.scanDate,
    summary: {
      total: vulns.length,
      critical: critical.length,
      high: high.length,
      medium: medium.length,
      low: low.length
    }
  }
}];
